put('Policy/Loc/LocPolicy.php',r'''namespace Guard\Policy\Loc;
use Guard\Collect\Information;
use Guard\Collect\Php\PhpSources;
use Guard\Collect\Php\SourceMetrics;
use Guard\Config\Loc\LimitConfig;
use Guard\Execution\Context;
use Guard\Execution\Plan;
use Guard\Policy\Policy;
use Guard\Policy\PolicyException;
use Guard\Policy\Loc\Assignment\FilePolicyAssigner;
use Guard\Policy\Loc\ClassLikeMetric\ClassLikeMetricViolationBuilder;
use Guard\Policy\Loc\FileMetric\FileMetricViolationBuilder;
use Guard\Policy\Loc\FunctionMetric\FunctionMetricViolationBuilder;
use Guard\Reporting\Finding;
/** Applies metric profiles to collected PHP metrics without accessing source files. */
final class LocPolicy implements Policy
{
    /** Evaluates assignments and metric limits in the established file and rule order. */
    public function evaluate(Information $information, Context $context): Plan
    {
        if (!$information instanceof PhpSources) {
            throw new PolicyException('LocPolicy requires PhpSources. Register it for that information type.');
        }
        $config = $context->configuration->metrics;
        if ($config === null) {
            return new Plan([], []);
        }
        $findings = [];
        foreach ((new FilePolicyAssigner())->assign($config, $information->paths) as $assignment) {
            foreach ($this->violations($information->metrics[$assignment->path], $assignment->policy->limits, $assignment->policy->name) as $violation) {
                $findings[] = new Finding($violation->path, 'metrics.' . $violation->rule, 'required', $violation->message);
            }
        }
        return new Plan($findings, []);
    }
    /** @return list<Violation> */
    public function violations(SourceMetrics $metrics, LimitConfig $limits, string $profile = 'standard'): array
    {
        if (!$metrics->readable) {
            return [];
        }
        return array_merge(
            (new FileMetricViolationBuilder())->violations($metrics->file, $limits, $profile),
            (new ClassLikeMetricViolationBuilder())->violations($metrics->file->path, $metrics->classes, $limits, $profile),
            (new FunctionMetricViolationBuilder())->violations($metrics->file->path, $metrics->functions, $limits, $profile),
        );
    }
}''')
put('Policy/Tree/TreePolicy.php',r'''namespace Guard\Policy\Tree;
use Guard\Collect\Information;
use Guard\Collect\Tree\DirectoryTree;
use Guard\Execution\Context;
use Guard\Execution\Plan;
use Guard\Policy\Policy;
use Guard\Policy\PolicyException;
use Guard\Reporting\Finding;
/** Evaluates every matching directory rule against the same collected tree. */
final class TreePolicy implements Policy
{
    /** Overlapping directory rules remain independent. */
    public function evaluate(Information $information, Context $context): Plan
    {
        if (!$information instanceof DirectoryTree) {
            throw new PolicyException('TreePolicy requires DirectoryTree. Register it for that information type.');
        }
        $config = $context->configuration->structure;
        $findings = [];
        foreach ($config === null ? [] : $config->rules as $rule) {
            foreach ($information->listings as $listing) {
                if ((new DirectoryPatternMatcher())->matches($rule->path, $listing->relativePath)) {
                    foreach ((new DirectoryRuleInspector())->inspect($rule, $listing, $information->listings) as $violation) {
                        $findings[] = new Finding($violation->path, 'structure.' . $violation->rule, 'required', $violation->message);
                    }
                }
            }
        }
        return new Plan($findings, []);
    }
}''')
put('Policy/Doc/DocPolicy.php',r'''namespace Guard\Policy\Doc;
use Guard\Collect\Information;
use Guard\Collect\Markdown\MarkdownDocuments;
use Guard\Collect\Markdown\Parsing\Heading;
use Guard\Config\Doc\DocumentationConfig;
use Guard\Execution\Context;
use Guard\Execution\Plan;
use Guard\Policy\Policy;
use Guard\Policy\PolicyException;
use Guard\Reporting\Finding;
/** Applies heading and declaration policies to a collected Markdown snapshot. */
final class DocPolicy implements Policy
{
    /** Evaluates declared files first and undeclared files in scan-pattern order. */
    public function evaluate(Information $information, Context $context): Plan
    {
        if (!$information instanceof MarkdownDocuments) {
            throw new PolicyException('DocPolicy requires MarkdownDocuments. Register it for that information type.');
        }
        $config = $context->configuration->documentation;
        if ($config === null) {
            return new Plan([], []);
        }
        $violations = [];
        foreach ($config->documents as $document) {
            $headings = $information->headings[$document->path];
            if ($headings === null) {
                $violations[] = (new ViolationFactory())->missingDocument($document->path, $config->configName);
                continue;
            }
            $maxLevel = $document->maxLevel;
            $headings = array_values(array_filter($headings, static fn (Heading $heading): bool => $heading->level <= $maxLevel));
            $violations = array_merge($violations, (new HeadingStructureComparator())->compare($document, $headings, $config->configName));
        }
        $findings = [];
        foreach (array_merge($violations, $this->undeclared($information, $config)) as $violation) {
            $findings[] = new Finding($violation->path, 'documentation.' . $violation->rule, 'required', $violation->message);
        }
        return new Plan($findings, []);
    }
    /** @return list<Violation> */
    public function undeclared(MarkdownDocuments $information, DocumentationConfig $config): array
    {
        $reported = array_fill_keys($information->excluded, true);
        foreach ($config->documents as $document) {
            $reported[$document->path] = true;
        }
        $violations = [];
        foreach ($information->discovered as $pattern => $paths) {
            foreach ($paths as $path) {
                if (!isset($reported[$path])) {
                    $reported[$path] = true;
                    $violations[] = (new ViolationFactory())->undeclaredDocument($path, $pattern, $config->configName);
                }
            }
        }
        return $violations;
    }
}''')
put('Document/DocumentFailure.php',r'''namespace Guard\Document;
use Guard\Policy\PolicyException;
use JsonException;
use Nette\Neon\Exception as NeonException;
use RuntimeException;
/** Adds the target path to parsing and policy errors with stable CLI messages. */
final class DocumentFailure
{
    /** Returns the original exception category with document context. */
    public function at(string $path, RuntimeException|JsonException|NeonException $exception): RuntimeException|JsonException|NeonException
    {
        if ($exception instanceof JsonException) {
            return new JsonException('Invalid JSON value in ' . $path . '. Correct the document or repair value: ' . $exception->getMessage(), 0, $exception);
        }
        if ($exception instanceof NeonException) {
            return new NeonException('Invalid NEON value in ' . $path . '. Correct the document or repair value: ' . $exception->getMessage(), 0, $exception);
        }
        return new PolicyException('Cannot process ' . $path . ': ' . $exception->getMessage(), 0, $exception);
    }
}''')
put('Collect/Configuration/ConfigurationCollector.php',r'''namespace Guard\Collect\Configuration;
use Guard\Collect\Collector;
use Guard\Document\DataDocument;
use Guard\Document\PhpDocument;
use Guard\Document\XmlDocument;
use Guard\Document\DocumentFailure;
use Guard\Execution\Context;
use Guard\Execution\TargetPath;
use Guard\Policy\PolicyException;
use Guard\Policy\Rule;
use JsonException;
use Nette\Neon\Exception as NeonException;
use RuntimeException;
/** Resolves and parses each configuration document once for its field policies. */
final class ConfigurationCollector implements Collector
{
    /** @return list<ConfigurationDocument> */
    public function collect(Context $context): array
    {
        /** @var array<string, non-empty-list<Rule>> $groups */
        $groups = [];
        foreach ($context->configuration->rules as $rule) {
            $path = (new TargetPath())->resolve($context->configuration->root, $rule->file);
            if (realpath($path) === realpath($context->configPath)) {
                throw new PolicyException('Rule ' . $rule->id . ' targets guard.yaml itself. Policies cannot rewrite their own constraints.');
            }
            $groups[$path][] = $rule;
        }
        $documents = [];
        foreach ($groups as $path => $rules) {
            $documents[] = $this->read($path, $rules);
        }
        return $documents;
    }
    /** @param list<Rule> $rules */
    public function read(string $path, array $rules): ConfigurationDocument
    {
        try {
            if ($rules === []) {
                throw new PolicyException('A file plan requires at least one configuration rule.');
            }
            $source = file_get_contents($path);
            if ($source === false) {
                throw new PolicyException('Cannot read ' . $path . '. Check file permissions.');
            }
            $format = $rules[0]->format;
            $document = match ($format) {
                'xml' => new XmlDocument($source),
                'php' => new PhpDocument($source),
                default => new DataDocument($format, $source),
            };
            return new ConfigurationDocument($path, $source, $format, $document, $rules);
        } catch (RuntimeException|JsonException|NeonException $exception) {
            throw (new DocumentFailure())->at($path, $exception);
        }
    }
}''')
put('Policy/Configuration/ConfigurationPolicy.php',r'''namespace Guard\Policy\Configuration;
use Guard\Collect\Information;
use Guard\Collect\Configuration\ConfigurationDocument;
use Guard\Document\DocumentFailure;
use Guard\Execution\Context;
use Guard\Execution\FileChange;
use Guard\Execution\Plan;
use Guard\Policy\Policy;
use Guard\Policy\PolicyException;
use Guard\Policy\RuleEvaluator;
use JsonException;
use Nette\Neon\Exception as NeonException;
use RuntimeException;
/** Plans repairs and rechecks all overlapping field constraints before writes. */
final class ConfigurationPolicy implements Policy
{
    /** Evaluates a private document copy so other policies see the collected input. */
    public function evaluate(Information $information, Context $context): Plan
    {
        if (!$information instanceof ConfigurationDocument) {
            throw new PolicyException('ConfigurationPolicy requires ConfigurationDocument. Register it for that information type.');
        }
        try {
            return $this->plan($information, $context->repair);
        } catch (RuntimeException|JsonException|NeonException $exception) {
            throw (new DocumentFailure())->at($information->path, $exception);
        }
    }
    /** Evaluates the collected document and returns proposed bytes without filesystem access. */
    public function plan(ConfigurationDocument $information, bool $repair): Plan
    {
        $document = clone $information->document;
        $evaluator = new RuleEvaluator();
        $changed = false;
        foreach ($information->rules as $rule) {
            if ($rule->format !== $information->format) {
                throw new PolicyException('Conflicting formats for ' . $rule->file . '. Use one format for all its rules.');
            }
            if ($repair && $rule->repairable && !$evaluator->accepts($rule, $document)) {
                $document->write($rule->select, $rule->repair);
                $changed = true;
            }
        }
        $findings = [];
        foreach ($information->rules as $rule) {
            if (!$evaluator->accepts($rule, $document)) {
                $findings[] = $evaluator->finding($rule);
            }
        }
        return new Plan($findings, $changed ? [new FileChange($information->path, $information->source, $document->encode())] : [], $findings);
    }
}''')
