put('Collect/Filesystem/NativeFilesystem',r'''
/** Performs the native filesystem operations used by a shared snapshot. */
final class NativeFilesystem implements Filesystem
{
    /** Reads path facts and resolves aliases for deduplication. */
    public function inspect(string $path): Entry
    {
        return new Entry(is_dir($path), is_file($path), is_link($path), realpath($path) ?: $path);
    }
    /** @return list<string>|false */
    public function entries(string $path): array|false
    {
        $entries = @scandir($path);
        return $entries === false ? false : array_values(array_diff($entries, ['.', '..']));
    }
    /** Reads a file once when the request needs content. */
    public function read(string $path): string|false
    {
        return @file_get_contents($path);
    }
}
''')
put('Collect/Filesystem/Snapshot',r'''
/** Caches path facts and directory reads across every selection in one invocation. */
final class Snapshot
{
    /** @var array<string, Entry> */
    private array $entries = [];
    /** @var array<string, list<string>|false> */
    private array $directories = [];
    public function __construct(private Filesystem $filesystem)
    {
    }
    /** Returns path facts without repeating stat calls for overlapping selections. */
    public function inspect(string $path): Entry
    {
        return $this->entries[$path] ??= $this->filesystem->inspect($path);
    }
    /** Reads a physical directory at most once, including across symlink aliases.
     * @return list<string>|false
     */
    public function entries(string $path): array|false
    {
        $identity = $this->inspect($path)->identity;
        if (!array_key_exists($identity, $this->directories)) {
            $this->directories[$identity] = $this->filesystem->entries($path);
        }
        return $this->directories[$identity];
    }
    /** Reads a selected file; the collector groups all demands before calling this. */
    public function read(string $path): string|false
    {
        return $this->filesystem->read($path);
    }
}
''')
put('Collect/Filesystem/Path',r'''
/** Resolves and normalizes paths for shared filesystem selection. */
final class Path
{
    /** Resolves a path without changing its project-relative spelling. */
    public function absolute(string $root, string $path): string
    {
        return rtrim(str_starts_with($path, '/') ? $path : $root . ($path === '.' ? '' : '/' . $path), '/');
    }
    /** Removes redundant separators and dot segments for queue deduplication. */
    public function normalize(string $path): string
    {
        $parts = [];
        foreach (explode('/', str_replace('\\', '/', $path)) as $part) {
            if ($part === '' || $part === '.') {
                continue;
            }
            if ($part === '..' && $parts !== [] && end($parts) !== '..') {
                array_pop($parts);
            } else {
                $parts[] = $part;
            }
        }
        $result = (str_starts_with($path, '/') ? '/' : '') . implode('/', $parts);
        return $result === '' ? '.' : $result;
    }
    /** Returns a root-relative path when possible. */
    public function relative(string $root, string $path): string
    {
        $prefix = rtrim(str_replace('\\', '/', $root), '/') . '/';
        $path = str_replace('\\', '/', $path);
        return rtrim($path, '/') === rtrim($prefix, '/') ? '.' : (str_starts_with($path, $prefix) ? substr($path, strlen($prefix)) : $path);
    }
    /** Joins a root-relative directory and child name. */
    public function child(string $directory, string $name): string
    {
        return $directory === '.' ? $name : $directory . '/' . $name;
    }
}
''')
put('Collect/Filesystem/QueryResult',r'''
use Guard\Collect\DirectoryListing;
use Guard\Collect\FileRecord;

/** Accumulates one selection while the shared directory queue advances. */
final class QueryResult
{
    /** @var array<array-key, FileRecord> */
    private array $files = [];
    /** @var array<string, DirectoryListing> */
    private array $directories = [];
    private ?\Throwable $failure = null;
    /** Adds a selected path without duplicating overlapping roots. */
    public function addFile(FileRecord $file): void
    {
        $this->files[$file->relativePath] = $file;
    }
    /** Adds a filtered directory listing. */
    public function addDirectory(DirectoryListing $directory): void
    {
        $this->directories[$directory->relativePath] = $directory;
    }
    /** Keeps the first selection error for deferred policy evaluation. */
    public function fail(\Throwable $failure): void
    {
        $this->failure ??= $failure;
    }
    /** @return array<array-key, FileRecord> */
    public function files(): array
    {
        ksort($this->files);
        return $this->files;
    }
    /** @return array<string, DirectoryListing> */
    public function directories(): array
    {
        ksort($this->directories);
        return $this->directories;
    }
    /** Returns an error encountered during selection. */
    public function failure(): ?\Throwable
    {
        return $this->failure;
    }
