/** Merges all requests for a directory before it is visited, parents first. */
final class WalkQueue
{
    /** @var array<int, array<string, list<Route>>> */
    private array $levels = [];
    /** Adds a route to the directory's existing queue entry. */
    public function add(string $path, Route $route): void
    {
        $this->levels[substr_count($path, '/')][$path][] = $route;
    }
    /** Returns the next directory and all its requests, or null when finished.
     * @return ?array{string, list<Route>}
     */
    public function next(): ?array
    {
        if ($this->levels === []) {
            return null;
        }
        ksort($this->levels);
        $depth = array_key_first($this->levels);
        $path = array_key_first($this->levels[$depth]);
        $routes = $this->levels[$depth][$path];
        unset($this->levels[$depth][$path]);
        if ($this->levels[$depth] === []) {
            unset($this->levels[$depth]);
        }
        return [$path, $routes];
    }
}
''')
put('Collect/Matching/GlobMatcher',r'''
/** Advances segment glob states during one directory traversal. */
final class GlobMatcher
{
    /** Matches one child name; double stars consume only visible non-symlink directories.
     * @param list<string> $segments
     * @param list<int> $positions
     * @return list<int>
     */
    public function advance(array $segments, array $positions, string $name, bool $directory, bool $link): array
    {
        $active = array_fill_keys($positions, true);
        foreach ($segments as $index => $segment) {
            if (isset($active[$index]) && $segment === '**') {
                $active[$index + 1] = true;
            }
        }
        $next = [];
        foreach ($segments as $index => $segment) {
            if (!isset($active[$index])) {
                continue;
            }
            if ($segment === '**') {
                if ($directory && !$link && !str_starts_with($name, '.')) {
                    $next[$index] = true;
                }
                continue;
            }
            $wildcard = preg_match('/[*?\[]/', $segment) === 1;
            if ($wildcard ? !str_starts_with($name, '.') && fnmatch($segment, $name) : $segment === $name) {
                $next[$index + 1] = true;
            }
        }
        if ($directory) {
            unset($next[count($segments)]);
        }
        return array_keys($next);
    }
}
''')
