            $this->active[$id] = true;
            try {
                $this->values[$id] = $this->structurers[$id]->structure($this);
            } catch (Throwable $error) {
                $this->values[$id] = $error;
            } finally {
                unset($this->active[$id]);
            }
        }
        $value = $this->values[$id];
        if ($value instanceof Throwable) {
            throw $value;
        }
        return $value;
    }
}
