use Guard\Collect\DirectoryListing;
use Guard\Collect\FileRecord;
use Guard\Collect\Input;
use Guard\Collect\Matching\GlobMatcher;
use Guard\Collect\Matching\SelectionFilter;
use Guard\Collect\Selection;
use Guard\Execution\TargetPath;
use Guard\Policy\PolicyException;

/** Traverses the union of every registered selection in one shared directory queue. */
final class Discovery
{
    public function __construct(private Snapshot $snapshot)
    {
    }
    /** Builds all selections together; individual failures remain attached to their input.
     * @param array<string, Input> $inputs
     * @return array<string, QueryResult>
     */
    public function discover(string $root, array $inputs): array
    {
        $queue = new WalkQueue();
        $results = [];
        foreach ($inputs as $id => $input) {
            $result = new QueryResult();
            $results[$id] = $result;
            try {
                $this->seed($root, $id, $input->selection, $queue, $result);
            } catch (PolicyException $error) {
                $result->fail($error);
            }
        }
        while (($next = $queue->next()) !== null) {
            [$path, $routes] = $next;
            $entries = $this->snapshot->entries($path);
            $seen = [];
            foreach ($routes as $route) {
                $key = json_encode([$route->query, $route->segments, $route->positions]);
                if (isset($seen[$key])) {
                    continue;
                }
                $seen[$key] = true;
                $selection = $inputs[$route->query]->selection;
                if ($entries === false) {
                    if ($selection->mode !== 'patterns') {
                        $results[$route->query]->fail(new PolicyException('Failed to read directory: ' . $path));
                    }
                    continue;
                }
                $this->visit($root, $path, $entries, $route, $selection, $queue, $results[$route->query]);
            }
        }
        return $results;
    }
    /** Queues directory roots and records exact file requests without directory scans.
     * @throws PolicyException
     */
    public function seed(string $root, string $id, Selection $selection, WalkQueue $queue, QueryResult $result): void
    {
        $paths = new Path();
        foreach ($selection->paths as $path) {
            if ($selection->mode === 'patterns') {
                $pattern = preg_replace('#/+#', '/', $path) ?? $path;
                while (str_starts_with($pattern, './')) {
                    $pattern = substr($pattern, 2);
                }
                $queue->add($paths->normalize($root), new Route($id, explode('/', rtrim($pattern, '/')), [0], []));
                continue;
            }
            $absolute = $selection->confined ? (new TargetPath($this->snapshot))->resolve($root, $path) : $paths->absolute($root, $path);
            $entry = $this->snapshot->inspect($absolute);
            if ($selection->forbiddenPath !== null && $entry->identity === $this->snapshot->inspect($selection->forbiddenPath)->identity) {
                throw new PolicyException($selection->forbiddenMessage);
            }
            if ($selection->mode === 'files') {
                $result->addFile(new FileRecord($absolute, $path, $entry));
                continue;
            }
            if (!$entry->directory) {
                throw new PolicyException(str_replace(['{path}', '{absolute}'], [$path, $absolute], $selection->rootError));
            }
            $queue->add($paths->normalize($absolute), new Route($id, [], [], []));
        }
    }
    /** Routes every directory entry to all interested selections before descending.
     * @param list<string> $entries
     */
    public function visit(string $root, string $path, array $entries, Route $route, Selection $selection, WalkQueue $queue, QueryResult $result): void
    {
        $paths = new Path();
        $relative = $paths->relative($root, $path);
        $files = [];
        $directories = [];
        $ancestors = array_merge($route->ancestors, [$this->snapshot->inspect($path)->identity]);
        foreach ($entries as $name) {
            $absolute = $path . '/' . $name;
            $child = $paths->child($relative, $name);
            $entry = $this->snapshot->inspect($absolute);
            if ($selection->mode === 'patterns') {
                $positions = (new GlobMatcher())->advance($route->segments, $route->positions, $name, $entry->directory, $entry->link);
                if ($entry->directory && $positions !== []) {
                    $queue->add($absolute, new Route($route->query, $route->segments, $positions, $ancestors));
                } elseif ($entry->file && in_array(count($route->segments), $positions, true)) {
                    $result->addFile(new FileRecord($absolute, $child, $entry));
                }
                continue;
            }
            if (!(new SelectionFilter())->includes($selection, $child)) {
                continue;
            }
            if ($entry->directory) {
                $directories[] = $name;
                if (($selection->mode === 'directories' || !$entry->link) && !in_array($entry->identity, $ancestors, true)) {
                    $queue->add($absolute, new Route($route->query, [], [], $ancestors));
                }
            } else {
                $files[] = $name;
                if (str_ends_with($child, $selection->suffix)) {
                    $result->addFile(new FileRecord($absolute, $child, $entry));
                }
            }
        }
        if ($selection->mode === 'directories') {
            sort($files);
            sort($directories);
            $result->addDirectory(new DirectoryListing($relative, $files, $directories));
        }
    }
}
