    public function visit(string $root, string $path, array|false $entries, array $routes, array $inputs, WalkQueue $queue, array $results): void
    {
        $active = [];
        $directories = [];
        $files = [];
        foreach ($routes as $route) {
            $key = $route->query . "\0" . implode('/', $route->segments) . "\0" . implode(',', $route->positions);
            $active[$key] = $route;
            if ($entries === false && $inputs[$route->query]->selection->mode !== 'patterns') {
                $results[$route->query]->fail(new PolicyException('Failed to read directory: ' . $path));
            }
        }
        $paths = new Path();
