            if ($inputs[$route->query]->selection->mode === 'directories' && $entries !== false) {
                $fileNames = array_values($files[$route->query] ?? []);
                $dirNames = array_values($directories[$route->query] ?? []);
                sort($fileNames);
                sort($dirNames);
